        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birthdate_estimated AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birthdate_estimated,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.first_anc_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS first_anc_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.age_years_at_first_anc_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS age_years_at_first_anc_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dead AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dead,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.death_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS death_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.arv_number_identifier AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS arv_number_identifier,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_previous_pregnancy_groups AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_previous_pregnancy_groups,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.number_of_distinct_previous_pregnancies AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS number_of_distinct_previous_pregnancies,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.latest_previous_delivery_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS latest_previous_delivery_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_pregnancy_number AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_pregnancy_number,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_mode_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_mode_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_assisted_vaginal_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_assisted_vaginal_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_assisted_delivery_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_assisted_delivery_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_mode_of_delivery_details AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_mode_of_delivery_details,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_multiple_gestation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_multiple_gestation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_number_of_babies AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_number_of_babies,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_delivery_date_year AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_delivery_date_year,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_outcome_of_baby_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_outcome_of_baby_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_baby_birthweight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_baby_birthweight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_labour_duration_hours AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_labour_duration_hours,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.prev_preg_gestational_age_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS prev_preg_gestational_age_at_birth
    FROM mahis_pivot p
    GROUP BY p.person_id
)

SELECT * FROM woman_level ORDER BY person_id;
